"""dataset.py: Dataset class for loading rendered views and camera poses from the dataset generated by render_scene.py.
"""


from pathlib import Path
import numpy as np
import torch
from PIL import Image
from torch.utils.data import Dataset

import csv



class ViewDataset(Dataset):
    def __init__(self, root, split="training", mode="rotate", transform=None, target_transform=None):
        self.root = Path(root) / split
        self.transform = transform
        self.target_transform = target_transform
        self.split = split
        self.mode = mode
        self.samples = []
        self.scene_info = {}
        self.scene_intrinsics = {}

        if not self.root.exists():
            raise FileNotFoundError(f"Dataset split not found: {self.root}")

        scene_dirs = sorted(p for p in self.root.iterdir() if p.is_dir())
        if not scene_dirs:
            raise ValueError(f"No scene directories found in {self.root}")

        for scene_dir in scene_dirs:
            image_list = []
            csv_path = scene_dir / "camera_matrices.csv"
            intrinsic_path = scene_dir / "intrinsics.csv"
            if not csv_path.exists():
                raise FileNotFoundError(f"camera_matrices.csv not found in {scene_dir}")
            if not intrinsic_path.exists():
                raise FileNotFoundError(f"intrinsics.csv not found in {scene_dir}")
            idx = 0
            with open(csv_path, newline="") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    filename = row.get("filename")
                    if not filename:
                        continue
                    mat = np.zeros((4, 4), dtype=np.float32)
                    for j in range(16):
                        mat.flat[j] = float(row.get(f"m{j}", 0.0))
                    img_path = scene_dir / filename
                    if img_path.exists():
                        image_list.append((img_path, mat))
            with open(intrinsic_path, newline="") as f:
                reader = csv.reader(f)
                intrinsics = []
                for row in reader:
                    intrinsics.append([float(x) for x in row])
                intrinsics = np.array(intrinsics, dtype=np.float32)
            if len(image_list) <= 1:
                raise ValueError(f"Not enough images listed in camera_matrices.csv for {scene_dir}")
            self.scene_info[scene_dir] = image_list
            self.scene_intrinsics[scene_dir] = intrinsics
            for idx in range(len(image_list)):
                self.samples.append((scene_dir, idx))

        if not self.samples:
            raise ValueError(f"No valid image samples found in {self.root}")

    def __len__(self):
        return len(self.samples)

    def _load_image(self, path):
        image = Image.open(path).convert("RGB")
        if self.transform is not None:
            image = self.transform(image)
        else:
            image = torch.from_numpy(np.array(image)).permute(2, 0, 1).float() / 255.0
        return image

    def __getitem__(self, idx):
        scene_dir, img_idx = self.samples[idx]
        image_list = self.scene_info[scene_dir]

        input_path, input_pose = image_list[img_idx]
        intrinsics = self.scene_intrinsics[scene_dir]
        input_pose, intrinsics = torch.from_numpy(input_pose), torch.from_numpy(intrinsics)

        # choose target depending on split
        if self.split == "training":
            while True:
                next_idx = np.random.randint(0, len(image_list))
                if next_idx != img_idx:
                    break
        else:
            next_idx = (img_idx + 1) % len(image_list)

        target_path, target_pose = image_list[next_idx]
        target_pose = torch.from_numpy(target_pose)

        input_image = self._load_image(input_path)
        target_image = self._load_image(target_path)

        if self.target_transform is not None:
            target_image = self.target_transform(target_image)

        if self.mode == "rotate":
            return input_image, target_image, input_pose, target_pose, intrinsics
        elif self.mode == "generate":
            return target_image, target_pose, intrinsics
        else:
            raise ValueError(f"Invalid mode: {self.mode}")
